function a(e){return new Date(e).toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit",hour12:!0})}function o(e){return new Intl.DateTimeFormat("en-US",{weekday:"long",year:"numeric",month:"long",day:"numeric"}).format(new Date(e))}function r(e){return new Intl.DateTimeFormat("en-US",{year:"numeric",month:"long",day:"numeric"}).format(new Date(e))}function i(e,n){const t=new Date(`${e}T${n}`);return t.setHours(t.getHours()+1),t.toISOString()}export{r as a,a as b,i as c,o as f};
